using ClinicManagement.Api.Data; using ClinicManagement.Api.Domain; using Microsoft.EntityFrameworkCore;
namespace ClinicManagement.Api.Features.Treatments;
public record TreatmentOrderInput(string TreatmentName,Guid? MedicineId,Guid? PreferredBatchId,string? Route,decimal DoseQuantity,int? FrequencyHours,int NumberOfDoses,decimal? ProcedureUnitPrice,string? Instructions);
public record CreateTreatmentPlanRequest(DateTime StartsAt,string? Instructions,List<TreatmentOrderInput> Orders,bool SafetyAcknowledged=true);
public record AdministerDoseRequest(Guid? BatchId,decimal? QuantityUsed,string? Notes,DateTime? AdministeredAt);

public sealed class TreatmentsService(ClinicDbContext db)
{
 public async Task<object> CreatePlanAsync(Guid visitId,CreateTreatmentPlanRequest input,Guid userId,CancellationToken ct){if(input.Orders.Count==0)throw new ArgumentException("Add at least one medicine to this treatment.");var safety=await db.Visits.Where(x=>x.Id==visitId&&(x.Status==VisitStatus.OPEN||x.Status==VisitStatus.ACTIVE)).Select(x=>new{x.Patient.Allergies,x.Patient.MedicalConditions,x.Patient.CurrentMedication}).SingleOrDefaultAsync(ct);if(safety is null)throw new ArgumentException("An active visit is required.");if(!input.SafetyAcknowledged&&(!string.IsNullOrWhiteSpace(safety.Allergies)||!string.IsNullOrWhiteSpace(safety.MedicalConditions)||!string.IsNullOrWhiteSpace(safety.CurrentMedication)))throw new ArgumentException("Review and acknowledge the patient's allergy, medical-condition and current-medication warnings before creating treatment.");await using var tx=await db.Database.BeginTransactionAsync(ct);var plan=new TreatmentPlan{VisitId=visitId,StartsAt=input.StartsAt.ToUniversalTime(),Instructions=input.Instructions,CreatedById=userId};decimal total=0;foreach(var item in input.Orders){if(item.MedicineId is null)throw new ArgumentException("Every treatment item must select a medicine or clinical supply from inventory.");if(item.DoseQuantity<=0||item.NumberOfDoses<=0)throw new ArgumentException("Dose quantity and number of doses must be positive.");var batch=item.PreferredBatchId is null?await db.MedicineBatches.Where(x=>x.MedicineId==item.MedicineId&&x.Medicine.IsActive&&x.IsActive&&x.QuantityRemaining>0&&(x.ExpiryDate==null||x.ExpiryDate>DateOnly.FromDateTime(DateTime.UtcNow))).OrderBy(x=>x.ExpiryDate).FirstOrDefaultAsync(ct):await db.MedicineBatches.SingleOrDefaultAsync(x=>x.Id==item.PreferredBatchId&&x.MedicineId==item.MedicineId&&x.Medicine.IsActive&&x.IsActive,ct);if(batch is null)throw new ArgumentException($"No usable stock batch exists for {item.TreatmentName}.");var quantity=item.DoseQuantity*item.NumberOfDoses;var name=string.IsNullOrWhiteSpace(item.TreatmentName)?await db.Medicines.Where(x=>x.Id==item.MedicineId).Select(x=>x.Name).SingleAsync(ct):item.TreatmentName.Trim();var order=new TreatmentOrder{TreatmentName=name,MedicineId=item.MedicineId,PreferredBatchId=batch.Id,Route=item.Route,DoseQuantity=item.DoseQuantity,FrequencyHours=item.FrequencyHours,NumberOfDoses=item.NumberOfDoses,TotalQuantity=quantity,LockedUnitPrice=batch.SellingPrice,TotalPrice=quantity*batch.SellingPrice,Instructions=item.Instructions};for(var i=0;i<item.NumberOfDoses;i++)order.Doses.Add(new TreatmentDose{ScheduledAt=plan.StartsAt.AddHours((item.FrequencyHours??0)*i)});plan.Orders.Add(order);total+=order.TotalPrice;}db.TreatmentPlans.Add(plan);var bill=await db.Bills.SingleOrDefaultAsync(x=>x.VisitId==visitId&&x.Status!="CANCELLED",ct);if(bill is null){bill=new Bill{BillNumber=$"BILL-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString("N")[..6].ToUpperInvariant()}",VisitId=visitId};db.Bills.Add(bill);}foreach(var order in plan.Orders)db.BillItems.Add(new BillItem{BillId=bill.Id,ItemType="MEDICINE",Description=order.TreatmentName,Quantity=order.TotalQuantity,UnitPrice=order.LockedUnitPrice,Amount=order.TotalPrice,SourceId=order.Id});bill.OriginalAmount+=total;bill.TotalAmount=bill.OriginalAmount+bill.AdjustmentAmount;bill.Status=BillStatus(bill.TotalAmount,bill.PaidAmount);db.AuditLogs.Add(new AuditLog{UserId=userId,Action="CREATE",EntityType="TreatmentPlan",EntityId=plan.Id.ToString(),NewValues=System.Text.Json.JsonSerializer.Serialize(new{input,safety})});await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return new{planId=plan.Id,billId=bill.Id,bill.BillNumber,total,bill.TotalAmount,bill.PaidAmount,balance=bill.TotalAmount-bill.PaidAmount,bill.Status,items=plan.Orders.Select(x=>new{x.Id,x.TreatmentName,x.TotalQuantity,x.LockedUnitPrice,x.TotalPrice})};}

 public async Task<object?> UpdatePlanAsync(Guid planId,CreateTreatmentPlanRequest input,Guid userId,CancellationToken ct)
 {
  if(input.Orders.Count==0)throw new ArgumentException("Add at least one medicine to this treatment.");
  await using var tx=await db.Database.BeginTransactionAsync(ct);
  var plan=await db.TreatmentPlans.Include(x=>x.Visit).Include(x=>x.Orders).ThenInclude(x=>x.Doses).SingleOrDefaultAsync(x=>x.Id==planId,ct);
  if(plan is null)return null;
  if(plan.Visit.Status!=VisitStatus.OPEN&&plan.Visit.Status!=VisitStatus.ACTIVE)throw new InvalidOperationException("Treatments on a closed visit cannot be edited.");
  if(plan.Orders.SelectMany(x=>x.Doses).Any(x=>x.Status!=DoseStatus.SCHEDULED))throw new InvalidOperationException("This treatment already has given, late, missed, or cancelled doses. Preserve its history and create a new correction treatment instead.");
  var bill=await db.Bills.Include(x=>x.Items).SingleOrDefaultAsync(x=>x.VisitId==plan.VisitId&&x.Status!="CANCELLED",ct);
  if(bill is null)throw new InvalidOperationException("The treatment bill could not be found.");
  var oldOrderIds=plan.Orders.Select(x=>x.Id).ToHashSet();
  var oldSnapshot=System.Text.Json.JsonSerializer.Serialize(new{plan.Id,plan.StartsAt,plan.Instructions,orders=plan.Orders.Select(x=>new{x.Id,x.TreatmentName,x.MedicineId,x.TotalQuantity,x.LockedUnitPrice,x.TotalPrice})});
  var newOrders=new List<TreatmentOrder>();decimal replacementTotal=0;
  foreach(var item in input.Orders)
  {
   if(item.MedicineId is null)throw new ArgumentException("Every treatment item must select a medicine or clinical supply from inventory.");
   if(item.DoseQuantity<=0||item.NumberOfDoses<=0)throw new ArgumentException("Dose quantity and number of doses must be positive.");
   var batch=item.PreferredBatchId is null?await db.MedicineBatches.Where(x=>x.MedicineId==item.MedicineId&&x.Medicine.IsActive&&x.IsActive&&x.QuantityRemaining>0&&(x.ExpiryDate==null||x.ExpiryDate>DateOnly.FromDateTime(DateTime.UtcNow))).OrderBy(x=>x.ExpiryDate).FirstOrDefaultAsync(ct):await db.MedicineBatches.SingleOrDefaultAsync(x=>x.Id==item.PreferredBatchId&&x.MedicineId==item.MedicineId&&x.Medicine.IsActive&&x.IsActive,ct);
   if(batch is null)throw new ArgumentException($"No usable stock batch exists for {item.TreatmentName}.");
   var quantity=item.DoseQuantity*item.NumberOfDoses;
   var name=string.IsNullOrWhiteSpace(item.TreatmentName)?await db.Medicines.Where(x=>x.Id==item.MedicineId).Select(x=>x.Name).SingleAsync(ct):item.TreatmentName.Trim();
   var order=new TreatmentOrder{TreatmentPlanId=plan.Id,TreatmentName=name,MedicineId=item.MedicineId,PreferredBatchId=batch.Id,Route=item.Route,DoseQuantity=item.DoseQuantity,FrequencyHours=item.FrequencyHours,NumberOfDoses=item.NumberOfDoses,TotalQuantity=quantity,LockedUnitPrice=batch.SellingPrice,TotalPrice=quantity*batch.SellingPrice,Instructions=item.Instructions};
   for(var i=0;i<item.NumberOfDoses;i++)order.Doses.Add(new TreatmentDose{ScheduledAt=input.StartsAt.ToUniversalTime().AddHours((item.FrequencyHours??0)*i)});
   newOrders.Add(order);replacementTotal+=order.TotalPrice;
  }
  var retainedTotal=bill.Items.Where(x=>x.SourceId is null||!oldOrderIds.Contains(x.SourceId.Value)).Sum(x=>x.Amount);
  var newOriginal=retainedTotal+replacementTotal;var newTotal=newOriginal+bill.AdjustmentAmount;
  if(newTotal<bill.PaidAmount)throw new InvalidOperationException("The corrected treatment total cannot be lower than payments already received. Reverse or adjust the payment first.");
  db.BillItems.RemoveRange(bill.Items.Where(x=>x.SourceId is not null&&oldOrderIds.Contains(x.SourceId.Value)));
  db.TreatmentOrders.RemoveRange(plan.Orders);
  plan.StartsAt=input.StartsAt.ToUniversalTime();plan.Instructions=input.Instructions;plan.UpdatedAt=DateTime.UtcNow;plan.Orders=newOrders;
  foreach(var order in newOrders)db.BillItems.Add(new BillItem{BillId=bill.Id,ItemType="MEDICINE",Description=order.TreatmentName,Quantity=order.TotalQuantity,UnitPrice=order.LockedUnitPrice,Amount=order.TotalPrice,SourceId=order.Id});
  bill.OriginalAmount=newOriginal;bill.TotalAmount=newTotal;bill.Status=BillStatus(bill.TotalAmount,bill.PaidAmount);bill.UpdatedAt=DateTime.UtcNow;
  db.AuditLogs.Add(new AuditLog{UserId=userId,Action="UPDATE",EntityType="TreatmentPlan",EntityId=plan.Id.ToString(),OldValues=oldSnapshot,NewValues=System.Text.Json.JsonSerializer.Serialize(input)});
  await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);
  return new{planId=plan.Id,billId=bill.Id,bill.BillNumber,total=replacementTotal,bill.TotalAmount,bill.PaidAmount,balance=bill.TotalAmount-bill.PaidAmount,bill.Status};
 }

 private static string BillStatus(decimal total,decimal paid)=>total<=0?"OPEN":paid>=total?"PAID":paid>0?"PARTIAL":"OPEN";
 public async Task<object> DueAsync(string scope,CancellationToken ct){var now=DateTime.UtcNow;var end=now.AddHours(24);var q=db.TreatmentDoses.AsNoTracking().Where(x=>x.Status==DoseStatus.SCHEDULED);q=scope.ToLowerInvariant() switch{"late"=>q.Where(x=>x.ScheduledAt<now),"upcoming"=>q.Where(x=>x.ScheduledAt>now&&x.ScheduledAt<=end),"missed"=>db.TreatmentDoses.AsNoTracking().Where(x=>x.Status==DoseStatus.MISSED),_=>q.Where(x=>x.ScheduledAt<=now)};var rows=await q.OrderBy(x=>x.ScheduledAt).Select(x=>new{x.Id,x.ScheduledAt,x.Status,x.TreatmentOrder.TreatmentName,x.TreatmentOrder.DoseQuantity,x.TreatmentOrder.Route,x.TreatmentOrder.MedicineId,x.TreatmentOrder.PreferredBatchId,patient=new{x.TreatmentOrder.TreatmentPlan.Visit.Patient.Id,x.TreatmentOrder.TreatmentPlan.Visit.Patient.PatientNumber,x.TreatmentOrder.TreatmentPlan.Visit.Patient.FirstName,x.TreatmentOrder.TreatmentPlan.Visit.Patient.LastName},visitId=x.TreatmentOrder.TreatmentPlan.VisitId}).ToListAsync(ct);var medicineIds=rows.Where(x=>x.MedicineId!=null).Select(x=>x.MedicineId!.Value).Distinct().ToList();var batches=await db.MedicineBatches.AsNoTracking().Where(b=>medicineIds.Contains(b.MedicineId)&&b.IsActive&&b.QuantityRemaining>0).OrderBy(b=>b.ExpiryDate).Select(b=>new{b.Id,b.MedicineId,b.BatchNumber,b.QuantityRemaining,b.ExpiryDate}).ToListAsync(ct);return rows.Select(x=>new{x.Id,x.ScheduledAt,x.Status,x.TreatmentName,x.DoseQuantity,x.Route,x.MedicineId,x.PreferredBatchId,x.patient,x.visitId,availableBatches=x.MedicineId is null?[]:batches.Where(b=>b.MedicineId==x.MedicineId).Select(b=>new{b.Id,b.BatchNumber,b.QuantityRemaining,b.ExpiryDate}).ToList()}).ToList();}
 public async Task<bool> AdministerAsync(Guid doseId,AdministerDoseRequest input,Guid userId,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(ct);var dose=await db.TreatmentDoses.Include(x=>x.TreatmentOrder).SingleOrDefaultAsync(x=>x.Id==doseId,ct);if(dose is null)return false;if(dose.Status!=DoseStatus.SCHEDULED)throw new InvalidOperationException("This dose has already been resolved.");var actual=(input.AdministeredAt??DateTime.UtcNow).ToUniversalTime();var quantity=input.QuantityUsed??dose.TreatmentOrder.DoseQuantity;if(dose.TreatmentOrder.MedicineId is not null){var batchId=input.BatchId??dose.TreatmentOrder.PreferredBatchId;var batch=await db.MedicineBatches.SingleOrDefaultAsync(x=>x.Id==batchId&&x.MedicineId==dose.TreatmentOrder.MedicineId&&x.IsActive,ct);if(batch is null||batch.QuantityRemaining<quantity)throw new InvalidOperationException("The selected batch has insufficient usable stock.");if(batch.ExpiryDate is not null&&batch.ExpiryDate<=DateOnly.FromDateTime(actual))throw new InvalidOperationException("Expired medicine cannot be administered.");batch.QuantityRemaining-=quantity;db.StockTransactions.Add(new StockTransaction{MedicineId=batch.MedicineId,MedicineBatchId=batch.Id,Type=MovementType.TREATMENT,QuantityChange=-quantity,BalanceAfter=batch.QuantityRemaining,Reason=$"Treatment dose {dose.Id}",ReferenceType="TreatmentDose",ReferenceId=dose.Id,PerformedById=userId});dose.MedicineBatchId=batch.Id;dose.QuantityUsed=quantity;}dose.AdministeredAt=actual;dose.AdministeredById=userId;dose.Notes=input.Notes;dose.Status=actual>dose.ScheduledAt.AddMinutes(30)?DoseStatus.LATE:DoseStatus.GIVEN;db.AuditLogs.Add(new AuditLog{UserId=userId,Action="ADMINISTER",EntityType="TreatmentDose",EntityId=dose.Id.ToString()});await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return true;}
 public async Task<bool> MissAsync(Guid doseId,string? reason,Guid userId,CancellationToken ct){var dose=await db.TreatmentDoses.FindAsync([doseId],ct);if(dose is null)return false;if(dose.Status!=DoseStatus.SCHEDULED)throw new InvalidOperationException("This dose has already been resolved.");dose.Status=DoseStatus.MISSED;dose.Notes=reason;dose.UpdatedAt=DateTime.UtcNow;db.AuditLogs.Add(new AuditLog{UserId=userId,Action="MISS",EntityType="TreatmentDose",EntityId=dose.Id.ToString(),NewValues=reason});await db.SaveChangesAsync(ct);return true;}
}
